"""RFC 9562 UUIDv7 generation for Python 3.12.

Python 3.12 does not yet expose ``uuid.uuid7()``.  This implementation makes
time-ordered UUIDs on the API server without requiring a PostgreSQL extension.
"""

from __future__ import annotations

import secrets
import threading
import time
from uuid import UUID


_lock = threading.Lock()
_last_timestamp_ms = -1
_last_rand_a = 0


def uuid7() -> UUID:
    """Return a monotonic UUIDv7 generated by this application server.

    UUIDv7 puts the Unix epoch millisecond timestamp in its most significant
    48 bits.  ``rand_a`` is incremented for IDs made in the same millisecond,
    retaining useful insertion locality while ``rand_b`` remains random.
    """
    global _last_timestamp_ms, _last_rand_a

    with _lock:
        timestamp_ms = time.time_ns() // 1_000_000
        if timestamp_ms > _last_timestamp_ms:
            _last_timestamp_ms = timestamp_ms
            _last_rand_a = secrets.randbits(12)
        else:
            # Keep ordering even if the clock moves backwards briefly.
            timestamp_ms = _last_timestamp_ms
            _last_rand_a += 1
            if _last_rand_a > 0xFFF:
                # Extremely unlikely (over 4096 IDs in one millisecond). Move
                # to the next logical millisecond rather than emitting a repeat.
                _last_timestamp_ms += 1
                timestamp_ms = _last_timestamp_ms
                _last_rand_a = secrets.randbits(12)

        value = (
            (timestamp_ms << 80)
            | (0x7 << 76)  # UUID version 7
            | (_last_rand_a << 64)
            | (0b10 << 62)  # RFC 4122 variant
            | secrets.randbits(62)
        )
    return UUID(int=value)
